#!/usr/bin/env node
// Добавляет загрузку ВИДЕО с устройства в форму поста («Подготовка постов» → «Новый пост») в проекте tg-channel-manager:
// MP4 до 50 МБ, индикатор прогресса, потоковая запись на диск на сервере.
// Запуск:  node add-video-upload.mjs [путь/к/проекту]      (по умолчанию — текущая папка)
// Требует поддержки видео в постах (add-parser.mjs, где она появилась). Нужен client_max_body_size 50m в nginx.
// Всё или ничего: если файл отличается от ожидаемого, скрипт ничего не меняет. Повторный запуск безопасен; копии — *.bak-upload.
// Новых зависимостей и изменений схемы БД нет.
import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';

const root = path.resolve(process.argv[2] || '.');
const dec = (s) => Buffer.from(s, 'base64').toString('utf8');
const p = (f) => path.join(root, f);
const sha = (s) => crypto.createHash('sha256').update(s).digest('hex');
const exists = (f) => fs.existsSync(p(f));
const read = (f) => fs.readFileSync(p(f), 'utf8');

const NEW_FILES = {
 "utils/upload.ts": "",
 "docs/SETUP.md": ""
};
const REPLACE = {
 "server/express/routes/uploads.js": {
  "content": "",
  "known": [
   "142910dafc6e2d6bc952faf69daca5f8c3f212baf3e527466b700316ec75bb77"
  ]
 }
};
const GROUPS = JSON.parse(dec(''));
const SOFT = JSON.parse(dec(''));
const APPENDS = JSON.parse(dec('W3sicmVsIjogImFzc2V0cy9tYWluLmNzcyIsICJtYXJrZXIiOiAiLnVwbG9hZC1wcm9ncmVzcyIsICJ0ZXh0IjogInByb2dyZXNzLnVwbG9hZC1wcm9ncmVzcyB7IGRpc3BsYXk6IGJsb2NrOyB3aWR0aDogMTAwJTsgaGVpZ2h0OiA4cHg7IG1hcmdpbi10b3A6IDEwcHg7IGFjY2VudC1jb2xvcjogdmFyKC0tYWNjZW50KTsgfVxuIn1d'));

const fail = (lines) => {
  console.error('Ничего не изменено:');
  for (const l of lines) console.error('  - ' + l);
  process.exit(1);
};

// 0. зависимости: видео уже должно поддерживаться в постах
const need = [];
if (!exists('server/express/uploads.js') || !/mp4/.test(read('server/express/uploads.js'))) need.push('поддержка видео в постах не установлена: сначала  node add-parser.mjs ' + root);
if (!exists('components/PostForm.vue') || !/isVideo/.test(read('components/PostForm.vue'))) need.push('форма поста без поддержки видео: сначала  node add-parser.mjs ' + root);
if (need.length) fail(need);

// 1. проверяем всё заранее
const conflicts = [];
const plan = { groups: [], replaces: [], soft: [], appends: [], skipped: [] };
for (const g of GROUPS) {
  if (!exists(g.rel)) { conflicts.push(`${g.rel}: файл не найден`); continue; }
  const text = read(g.rel);
  if (text.includes(g.marker)) continue;
  const missing = g.pairs.filter(([o]) => !text.includes(o)).length;
  if (missing) conflicts.push(`${g.rel}: не найдено ${missing} из ${g.pairs.length} мест для правки`);
  else plan.groups.push(g);
}
for (const [rel, { content, known }] of Object.entries(REPLACE)) {
  if (!exists(rel)) { conflicts.push(`${rel}: файл не найден`); continue; }
  const now = sha(read(rel));
  if (now === sha(dec(content))) continue;
  if (known.includes(now)) plan.replaces.push({ rel, content: dec(content) });
  else conflicts.push(`${rel}: файл изменён вами и целиком заменяется в этой версии (нужна ручная правка)`);
}
for (const g of SOFT) { // необязательное: README
  if (!exists(g.rel)) { plan.skipped.push(`${g.rel}: файла нет`); continue; }
  const text = read(g.rel);
  if (text.includes(g.marker)) continue;
  if (g.pairs.every(([o]) => text.includes(o))) plan.soft.push(g);
  else plan.skipped.push(`${g.rel}: отличается от ожидаемого, добавьте описание вручную`);
}
for (const a of APPENDS) {
  if (!exists(a.rel)) { conflicts.push(`${a.rel}: файл не найден`); continue; }
  if (!read(a.rel).includes(a.marker)) plan.appends.push(a);
}
if (conflicts.length) {
  conflicts.push('Внесите правки вручную по video-upload.patch (все файлы сразу).');
  fail(conflicts);
}

// 2. применяем
const backup = (file) => fs.existsSync(file + '.bak-upload') || fs.copyFileSync(file, file + '.bak-upload');
const write = (rel, text, mark) => {
  if (exists(rel)) backup(p(rel));
  fs.mkdirSync(path.dirname(p(rel)), { recursive: true });
  fs.writeFileSync(p(rel), text);
  console.log(`${mark} ${rel}`);
};
const apply = (rel, pairs) => {
  let out = read(rel);
  for (const [o, n] of pairs) out = out.replace(o, () => n);
  return out;
};
let changed = 0;
for (const [rel, b64] of Object.entries(NEW_FILES)) {
  if (exists(rel) && read(rel) === dec(b64)) console.log(`= ${rel}: без изменений`);
  else { write(rel, dec(b64), exists(rel) ? '~' : '+'); changed++; }
}
for (const { rel, content } of plan.replaces) { write(rel, content, '~'); changed++; }
for (const g of plan.groups) { write(g.rel, apply(g.rel, g.pairs), '~'); changed++; }
for (const g of plan.soft) { write(g.rel, apply(g.rel, g.pairs), '~'); changed++; }
for (const a of plan.appends) { write(a.rel, read(a.rel).replace(/\n*$/, '\n') + a.text, '~'); changed++; }
if (!changed) console.log('Всё уже применено.');
for (const s of plan.skipped) console.warn('! пропущено: ' + s);

console.log('\nГотово. Дальше:');
console.log('  1) nginx: client_max_body_size 50m;  (иначе видео получит 413), затем nginx -s reload;');
console.log('  2) npm run build && перезапуск приложения (pm2 restart ecosystem.config.cjs --update-env / systemctl restart / docker compose up -d --build);');
console.log('  3) обновите страницу в браузере через Ctrl+F5. Формат видео: MP4 (H.264) до 50 МБ.');
